import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{r as t,o,c as p,a as n,e as c,w as d,b as s,d as i,f as l}from"./app-7d619fc9.js";const r={},u=n("strong",null,"语法分析（Parser）",-1),k=n("strong",null,"抽象语法树（AST）",-1),v=n("strong",null,"运算符优先级到底是怎么实现的",-1),m=n("blockquote",null,[n("p",null,"本文用一个自写的迷你 DSL 做例子，代码可运行，不涉及任何专有项目。")],-1),g=l(`<h2 id="一、从-一串词-到-一棵树" tabindex="-1"><a class="header-anchor" href="#一、从-一串词-到-一棵树" aria-hidden="true">#</a> 一、从&quot;一串词&quot;到&quot;一棵树&quot;</h2><p>接着上一篇的迷你过滤 DSL，假设我们要解析这样的条件：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>age &gt;= 18 and active == &quot;true&quot;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>词法分析给我们的是<strong>扁平</strong>的 token：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>IDENT(age) GE(&gt;=) NUMBER(18) AND IDENT(active) EQ(==) STRING(true)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>它是&quot;平的&quot;——没有层次。但这句话其实有结构：它是一个 <strong>and</strong>，左边是 <code>age &gt;= 18</code>，右边是 <code>active == &quot;true&quot;</code>。<strong>parser 的活，就是把扁平 token 组装成表达这种结构的树</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>        And
       /    \\
   (age&gt;=18) (active==&quot;true&quot;)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>词法</strong>：字符 → 词（token）。</li><li><strong>语法</strong>：词 → 结构（AST）。<br> 这条边界很重要：lexer 不关心 <code>age &gt;= 18</code> 是什么意思，它只负责切词；&quot;它是个比较表达式&quot;是 parser 的判断。</li></ul><h2 id="二、先用文法把规则写下来" tabindex="-1"><a class="header-anchor" href="#二、先用文法把规则写下来" aria-hidden="true">#</a> 二、先用文法把规则写下来</h2><p>描述&quot;什么样的 token 序列是合法的&quot;，要用<strong>文法（grammar）</strong>。常用记号是 <strong>BNF/EBNF</strong>：</p><table><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td><code>::=</code></td><td>定义为 / 由……构成</td></tr><tr><td><code>&#39;or&#39;</code>（带引号）</td><td>终结符，真实 token</td></tr><tr><td><code>( )*</code></td><td>重复 0 次或多次</td></tr><tr><td><code>[ ]</code></td><td>可选（0 或 1 次）</td></tr><tr><td><code>|</code></td><td>或（多选一）</td></tr></tbody></table><p>我们这门条件 DSL 的文法（注意规则的<strong>排列顺序</strong>，下面会发现它就是优先级）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>expr       ::= orExpr
orExpr     ::= andExpr (&#39;or&#39;  andExpr)*      ← or  最外层
andExpr    ::= notExpr (&#39;and&#39; notExpr)*      ← and 里一层
notExpr    ::= &#39;not&#39; notExpr | primary       ← not 再里一层
primary    ::= &#39;(&#39; expr &#39;)&#39; | comparison     ← 最里层：括号 / 原子
comparison ::= IDENT (&#39;==&#39; | &#39;&gt;=&#39;) value
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="怎么读懂一行文法" tabindex="-1"><a class="header-anchor" href="#怎么读懂一行文法" aria-hidden="true">#</a> 怎么读懂一行文法</h3><p>BNF 乍看像天书，其实逐块拆开很简单。以 <code>orExpr ::= andExpr (&#39;or&#39; andExpr)*</code> 这行为例：</p><table><thead><tr><th>片段</th><th>读作</th></tr></thead><tbody><tr><td><code>orExpr ::=</code></td><td>&quot;一个 orExpr，由……构成&quot;</td></tr><tr><td><code>andExpr</code></td><td>必须<strong>以一个 andExpr 打头</strong></td></tr><tr><td><code>(&#39;or&#39; andExpr)</code></td><td>一组『<code>or</code> + 一个 andExpr』</td></tr><tr><td><code>( … )*</code></td><td>上面这组可以<strong>重复 0 次或多次</strong></td></tr></tbody></table><p>合起来：<strong>一个 orExpr = 一个 andExpr，后面接任意多个『or 加一个 andExpr』</strong>。所以 <code>a</code>、<code>a or b</code>、<code>a or b or c</code> 都是合法的 orExpr。</p><p>那注释里&quot;<strong>or 在最外层</strong>&quot;是什么意思？顶层规则 <code>expr</code> 直接展开成 <code>orExpr</code>，所以 <code>or</code> 是<strong>最先进入、最靠外</strong>的那一层；而它的操作数（左右两边）本身是更内层的 <code>andExpr</code>——也就是说 <code>or</code> 负责把&quot;一个个 and 表达式&quot;串起来。<strong>规则排得越靠外，运算符优先级越低</strong>（最后才结合）。下一节会看到，这个&quot;排列顺序&quot;正是优先级的来源。</p><h2 id="三、递归下降-一条规则-一个函数" tabindex="-1"><a class="header-anchor" href="#三、递归下降-一条规则-一个函数" aria-hidden="true">#</a> 三、递归下降：一条规则 = 一个函数</h2><p>**递归下降（recursive descent）**是最直观的解析方法，名字拆开看：</p><ul><li><strong>下降</strong>：从文法<strong>最顶层</strong>的规则（<code>expr</code>）出发，<strong>一层层往下</strong>拆到最小的 token。方向是自顶向下。</li><li><strong>递归</strong>：因为文法是递归定义的（<code>primary</code> 里又出现了 <code>expr</code>），实现它的函数自然会<strong>互相调用、甚至调用自己</strong>。</li></ul><p>实现规则很简单：<strong>一条文法规则，写成一个函数</strong>。</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Token</span><span class="token punctuation">&gt;</span></span> tokens<span class="token punctuation">;</span>
<span class="token keyword">int</span> pos<span class="token punctuation">;</span>

<span class="token class-name">Token</span> <span class="token function">peek</span><span class="token punctuation">(</span><span class="token punctuation">)</span>           <span class="token punctuation">{</span> <span class="token keyword">return</span> tokens<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>pos<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>        <span class="token comment">// 看当前，不消费</span>
<span class="token class-name">Token</span> <span class="token function">peek</span><span class="token punctuation">(</span><span class="token keyword">int</span> ahead<span class="token punctuation">)</span>  <span class="token punctuation">{</span> <span class="token keyword">return</span> tokens<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>pos <span class="token operator">+</span> ahead<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">// 向前看，不消费</span>
<span class="token class-name">Token</span> <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span>           <span class="token punctuation">{</span> <span class="token keyword">return</span> tokens<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>pos<span class="token operator">++</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>       <span class="token comment">// 消费一个</span>

<span class="token comment">// expr ::= orExpr</span>
<span class="token class-name">Node</span> <span class="token function">parseExpr</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token function">parseOr</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>

<span class="token comment">// orExpr ::= andExpr (&#39;or&#39; andExpr)*</span>
<span class="token class-name">Node</span> <span class="token function">parseOr</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">Node</span> left <span class="token operator">=</span> <span class="token function">parseAnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>              <span class="token comment">// ① 左操作数：先让 and 层吃一整块</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span><span class="token function">peek</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>type <span class="token operator">==</span> <span class="token constant">OR</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                          <span class="token comment">// ② 吃掉 &#39;or&#39;</span>
        <span class="token class-name">Node</span> right <span class="token operator">=</span> <span class="token function">parseAnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// ③ 右操作数：又让 and 层吃一整块</span>
        left <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Or</span><span class="token punctuation">(</span>left<span class="token punctuation">,</span> right<span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// ④ 用 OR 把两块拼起来</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> left<span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// andExpr ::= notExpr (&#39;and&#39; notExpr)*   —— 结构和 parseOr 一模一样</span>
<span class="token class-name">Node</span> <span class="token function">parseAnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">Node</span> left <span class="token operator">=</span> <span class="token function">parseNot</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span><span class="token function">peek</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>type <span class="token operator">==</span> <span class="token constant">AND</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">Node</span> right <span class="token operator">=</span> <span class="token function">parseNot</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        left <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">And</span><span class="token punctuation">(</span>left<span class="token punctuation">,</span> right<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> left<span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// notExpr ::= &#39;not&#39; notExpr | primary</span>
<span class="token class-name">Node</span> <span class="token function">parseNot</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">peek</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>type <span class="token operator">==</span> <span class="token constant">NOT</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Not</span><span class="token punctuation">(</span><span class="token function">parseNot</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// 递归调用自己，支持 not not a</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> <span class="token function">parsePrimary</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// primary ::= &#39;(&#39; expr &#39;)&#39; | comparison</span>
<span class="token class-name">Node</span> <span class="token function">parsePrimary</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">peek</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>type <span class="token operator">==</span> <span class="token constant">LPAREN</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                          <span class="token comment">// 吃 &#39;(&#39;</span>
        <span class="token class-name">Node</span> inner <span class="token operator">=</span> <span class="token function">parseExpr</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// 递归回到顶层 —— 括号里能塞一整个表达式</span>
        <span class="token function">expect</span><span class="token punctuation">(</span><span class="token constant">RPAREN</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                  <span class="token comment">// 吃 &#39;)&#39;</span>
        <span class="token keyword">return</span> inner<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> <span class="token function">parseComparison</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看出来了吗——<strong>代码的调用结构，和文法的规则结构长得一模一样</strong>。这就是递归下降最大的优点：直观、可读、好维护。</p><h2 id="四、【核心】优先级是怎么-长-进树里的" tabindex="-1"><a class="header-anchor" href="#四、【核心】优先级是怎么-长-进树里的" aria-hidden="true">#</a> 四、【核心】优先级是怎么&quot;长&quot;进树里的</h2><p>这是面试最爱问的点。规律记住一句：</p><blockquote><p><strong>越外层（越早被调用）的运算符，优先级越低、在树里越靠根；越内层的优先级越高、越靠叶子。</strong></p></blockquote><p>为什么这条调用链 <code>parseOr → parseAnd → parseNot → parsePrimary</code> 就能保证 <code>and</code> 比 <code>or</code> 优先级高？<strong>关键在这一步</strong>：</p><p><code>parseOr</code> 要取它的操作数时，<strong>不是抓一个 token，而是调用 <code>parseAnd</code></strong>；而 <code>parseAnd</code> 会<strong>贪心地把一整条 and 链先结合好再返回</strong>。所以等 <code>parseOr</code> 看到 <code>or</code> 时，所有更紧的 <code>and</code> 早就被打包成一个整体了。</p><p>拿 <code>a or b and c</code>（a/b/c 是原子条件）走一遍：</p><ol><li><code>parseOr</code> 调 <code>parseAnd</code> 取左操作数 → <code>parseAnd</code> 看到 <code>a</code> 后面是 <code>or</code>（不是 <code>and</code>），返回 <code>a</code>。<code>left = a</code>。</li><li><code>parseOr</code> 看到 <code>or</code>，吃掉，调 <code>parseAnd</code> 取右操作数。</li><li>这次 <code>parseAnd</code>：取到 <code>b</code>，发现后面是 <code>and</code> → 吃掉 → 取 <code>c</code> → <strong>结合成 <code>And(b, c)</code> 整体返回</strong>。</li><li><code>parseOr</code> 把两边拼起来：<code>Or(a, And(b, c))</code>。</li></ol><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>     Or
    /  \\
   a    And      ← and 在更深一层，绑得更紧
       /   \\
      b     c
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>and</code> 之所以先结合，正是因为它在调用链的<strong>内层</strong>、先被 <code>parseAnd</code> 贪心处理掉。<strong>优先级不是靠什么优先级表，而是靠函数调用的层级&quot;长&quot;出来的。</strong> 而括号 <code>(...)</code> 能强行改变这一切——因为 <code>parsePrimary</code> 遇到 <code>(</code> 会递归回 <code>parseExpr</code>，把括号里的内容当成一个最高优先级的整体。</p><h2 id="五、遇到歧义怎么办-向前看-lookahead" tabindex="-1"><a class="header-anchor" href="#五、遇到歧义怎么办-向前看-lookahead" aria-hidden="true">#</a> 五、遇到歧义怎么办：向前看（lookahead）</h2><p>有时解析到某处，<strong>同样的开头可能是两种结构</strong>，光看当前 token 决定不了。办法是<strong>向前看</strong>：偷看后面一两个 token（不消费），据此决定走哪条分支。</p><p>比如某 DSL 里，<code>IDENT</code> 开头既可能是比较 <code>name == &quot;x&quot;</code>，也可能是函数调用 <code>name(...)</code>。这时就 <code>peek(1)</code> 看第二个 token：是 <code>(</code> 就走函数调用分支，是 <code>==</code> 就走比较分支。<code>peek()</code>/<code>peek(1)</code> 这类&quot;只看不消费&quot;的侦察，正是消除歧义的核心手段。</p><h2 id="六、别让一行写错就崩-错误恢复" tabindex="-1"><a class="header-anchor" href="#六、别让一行写错就崩-错误恢复" aria-hidden="true">#</a> 六、别让一行写错就崩：错误恢复</h2><p>工业级解析器还要容忍输入不规范。常见做法是区分两种&quot;吃 token&quot;：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">Token</span> <span class="token function">consume</span><span class="token punctuation">(</span><span class="token class-name">Type</span> t<span class="token punctuation">)</span> <span class="token punctuation">{</span>                  <span class="token comment">// 硬：不匹配就抛异常</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">peek</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>type <span class="token operator">!=</span> t<span class="token punctuation">)</span> <span class="token keyword">throw</span> <span class="token function">error</span><span class="token punctuation">(</span><span class="token string">&quot;expected &quot;</span> <span class="token operator">+</span> t<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">void</span> <span class="token function">expect</span><span class="token punctuation">(</span><span class="token class-name">Type</span> t<span class="token punctuation">)</span> <span class="token punctuation">{</span>                    <span class="token comment">// 软：不匹配只记日志、不崩，继续解析</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">peek</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>type <span class="token operator">==</span> t<span class="token punctuation">)</span> pos<span class="token operator">++</span><span class="token punctuation">;</span>
    <span class="token keyword">else</span> <span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;recover: missing &quot;</span> <span class="token operator">+</span> t<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>&quot;必须存在&quot;的地方用 <code>consume</code>；可以容错的地方（比如某个右括号）用 <code>expect</code> 软恢复。再在最外层 <code>try/catch</code> 兜底，一条规则写错就不会拖垮整个解析。</p><h3 id="那括号里要是写错了呢" tabindex="-1"><a class="header-anchor" href="#那括号里要是写错了呢" aria-hidden="true">#</a> 那括号里要是写错了呢？</h3><p>回到第三节 <code>parsePrimary</code> 里的 <code>Node inner = parseExpr(); expect(RPAREN);</code>——很多人会问：<strong>要是括号里不是一个合法表达式，<code>parseExpr</code> 返回的不是正常结果怎么办？</strong></p><p>关键认知：<strong><code>parseExpr</code> 不会&quot;悄悄返回一个错的结果让大家忽略&quot;</strong>，它总会尽力按文法匹配出一个 Node；&quot;错&quot;会在<strong>检查点</strong>暴露，主要两处：</p><ul><li><strong>少了 <code>)</code></strong>（如 <code>(age &gt;= 18 or active == 1</code>）：parseExpr 把能解析的都解析完，游标停在 EOF；紧接着的 <code>expect(RPAREN)</code> 发现不是 <code>)</code> → <strong>在这里被抓住</strong>。</li><li><strong>括号里是垃圾</strong>（如 <code>(or active == 1)</code>，开头就是运算符）：一路往深走到 <code>comparison ::= IDENT …</code>，<code>consume(IDENT)</code> 发现当前是 <code>or</code> 而非标识符 → <strong>当场失败</strong>。</li></ul><p>接下来就是上面那两种策略：硬 <code>consume</code> 抛异常 → 冒泡到最外层 try/catch → 丢弃整条规则；软 <code>expect</code> → 返回残缺 AST 继续。</p><p>⚠️ 但软恢复有代价——它可能<strong>默默吞掉错误</strong>：比如 <code>(age &gt;= 18 active == 1)</code> 漏了 <code>and</code>/<code>or</code>，parseExpr 解析完 <code>age &gt;= 18</code> 就停了，<code>expect(RPAREN)</code> 看到的是 <code>active</code> 而非 <code>)</code>，软恢复会直接跳过、返回半截结果，不报错。<strong>所以&quot;不崩&quot;不等于&quot;全对&quot;</strong>——要更严格，就在检查点加硬校验（解析完必须正好停在 <code>)</code> 或 EOF，否则报 unexpected token）。健壮性，本质就是你把这些检查点设得多严。</p><h2 id="七、这些-antlr4-都能自动生成" tabindex="-1"><a class="header-anchor" href="#七、这些-antlr4-都能自动生成" aria-hidden="true">#</a> 七、这些 ANTLR4 都能自动生成</h2><p>上面这套（递归下降、优先级链、向前看），其实 <strong>ANTLR4 这类解析器生成器能帮你自动生成</strong>。你只写一份 <code>.g4</code> 文法——它和 BNF 几乎逐字一样，只是把 <code>::=</code> 换成 <code>:</code>、用 <code>;</code> 收尾：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>BNF :  orExpr ::= andExpr (&#39;or&#39; andExpr)*
g4  :  orExpr :  andExpr (&#39;or&#39; andExpr)* ;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>ANTLR4 甚至能直接写左递归 + 按规则顺序声明优先级，自动生成上面那条手写调用链。</p><p>那为什么还要懂手写？因为：<strong>懂手写，才真懂 ANTLR4 自动生成了什么</strong>，而不是把它当黑盒；而且 GCC、Clang 这些工业编译器很多反而手写递归下降，图的是更好的报错和控制力。取舍是：从零造一门干净的新 DSL → 用 ANTLR4 省事；解析固定庞大的旧语言、追求极致报错 → 手写。</p><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结" aria-hidden="true">#</a> 小结</h2><p>语法分析就是把扁平 token 组装成 AST 树。递归下降的精髓在于：<strong>代码结构 = 文法结构，运算符优先级靠函数调用的层级自然长出来</strong>（外层=低优先级=靠根，内层=高优先级=靠叶子）。再配上向前看消歧、软恢复容错，就是一个能用的解析器了。</p><p>有了 AST，下一步就是<strong>语义</strong>：遍历这棵树去做点什么——求值、类型检查，或者像静态分析里那样，把规则的语义注入到中间表示（IR）上。这个后面再聊。</p>`,54);function b(x,h){const a=t("RouterLink");return o(),p("div",null,[n("p",null,[c(a,{to:"/compilation/03lexical_analysis.html"},{default:d(()=>[s("上一篇")]),_:1}),s("我们把字符流切成了一串扁平的 token。这一篇讲编译器的第二步——"),u,s("：把这串扁平 token 组装成一棵有结构的"),k,s('，并重点讲清一个很多人觉得"玄"的问题——'),v,s("。")]),m,i(" more "),g])}const q=e(r,[["render",b],["__file","04recursive_descent_parser.html.vue"]]);export{q as default};
